INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0205-0001-0001-000000000001', '22222222-0002-0001-0001-000000000005', 'The Coordinate Revolution', 'How René Descartes merged algebra and geometry by inventing the coordinate system', 1, 'tutorial', 15, 5, 1637, 'René Descartes',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0205-0001-0001-000000000001', '33333333-0205-0001-0001-000000000001', 'multiple_choice', 'easy', 'Who invented the coordinate system we use today?', NULL, '[{"id":"a","text":"Isaac Newton"},{"id":"b","text":"Pythagoras"},{"id":"c","text":"René Descartes"},{"id":"d","text":"Archimedes"}]'::jsonb, '"c"'::jsonb, 'René Descartes introduced the Cartesian coordinate system in 1637. The word "Cartesian" comes from the Latin version of his name.', 'The coordinate system is named after him', 5, 1),
('44444444-0205-0001-0001-000000000002', '33333333-0205-0001-0001-000000000001', 'multiple_choice', 'easy', 'What are the two axes called on a coordinate plane?', NULL, '[{"id":"a","text":"Up axis and down axis"},{"id":"b","text":"x-axis and y-axis"},{"id":"c","text":"Length axis and width axis"},{"id":"d","text":"Left axis and right axis"}]'::jsonb, '"b"'::jsonb, 'The horizontal line is the x-axis and the vertical line is the y-axis. Together they divide the plane into four quadrants.', 'One goes left-right, the other goes up-down', 5, 2),
('44444444-0205-0001-0001-000000000003', '33333333-0205-0001-0001-000000000001', 'multiple_choice', 'easy', 'What is the point (0, 0) called?', NULL, '[{"id":"a","text":"The center"},{"id":"b","text":"The origin"},{"id":"c","text":"The vertex"},{"id":"d","text":"The base"}]'::jsonb, '"b"'::jsonb, 'The point where the x-axis and y-axis cross is called the origin. It is the starting point — (0, 0).', 'It is where everything starts from', 5, 3),
('44444444-0205-0001-0001-000000000004', '33333333-0205-0001-0001-000000000001', 'true_false', 'easy', 'True or False: In the point (3, 5), the 3 represents the horizontal position and the 5 represents the vertical position.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! In (x, y), the first number is horizontal (x) and the second is vertical (y). So (3, 5) means 3 right and 5 up.', 'x comes first (horizontal), y comes second (vertical)', 5, 4),
('44444444-0205-0001-0001-000000000005', '33333333-0205-0001-0001-000000000001', 'multiple_choice', 'easy', 'What did Descartes achieve by inventing coordinates?', NULL, '[{"id":"a","text":"He proved the Earth is round"},{"id":"b","text":"He connected algebra and geometry"},{"id":"c","text":"He invented calculus"},{"id":"d","text":"He discovered gravity"}]'::jsonb, '"b"'::jsonb, 'Descartes showed that algebraic equations could be drawn as geometric shapes, and geometric shapes could be described with equations. He connected the two fields.', 'Before him, algebra and geometry were separate subjects', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0205-0001-0001-000000000002', '22222222-0002-0001-0001-000000000005', 'Reading & Plotting Points', 'Practice identifying and placing points on a coordinate plane', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0205-0002-0001-000000000001', '33333333-0205-0001-0001-000000000002', 'multiple_choice', 'easy', 'What are the coordinates of a point that is 4 units right and 2 units up from the origin?', NULL, '[{"id":"a","text":"(2, 4)"},{"id":"b","text":"(4, 2)"},{"id":"c","text":"(4, -2)"},{"id":"d","text":"(-4, 2)"}]'::jsonb, '"b"'::jsonb, 'Right = positive x, up = positive y. So 4 right and 2 up = (4, 2). Remember: x first, y second.', 'Horizontal first, vertical second', 5, 1),
('44444444-0205-0002-0001-000000000002', '33333333-0205-0001-0001-000000000002', 'multiple_choice', 'easy', 'A point is at (-3, 5). Where is it on the coordinate plane?', NULL, '[{"id":"a","text":"3 right, 5 up"},{"id":"b","text":"3 left, 5 down"},{"id":"c","text":"3 left, 5 up"},{"id":"d","text":"5 left, 3 up"}]'::jsonb, '"c"'::jsonb, 'Negative x means left, positive y means up. So (-3, 5) is 3 left and 5 up from the origin.', 'Negative x = left, positive y = up', 5, 2),
('44444444-0205-0002-0001-000000000003', '33333333-0205-0001-0001-000000000002', 'fill_in_blank', 'easy', 'A point is 6 units to the left and 3 units down from the origin. What is its x-coordinate? (Type just the number)', NULL, NULL, '"-6"'::jsonb, 'Left means negative x. So the x-coordinate is -6. The full point would be (-6, -3).', 'Left from the origin = negative', 5, 3),
('44444444-0205-0002-0001-000000000004', '33333333-0205-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which quadrant contains the point (2, -4)?', NULL, '[{"id":"a","text":"Quadrant I (top right)"},{"id":"b","text":"Quadrant II (top left)"},{"id":"c","text":"Quadrant III (bottom left)"},{"id":"d","text":"Quadrant IV (bottom right)"}]'::jsonb, '"d"'::jsonb, 'Positive x = right, negative y = down. That puts us in the bottom-right area, which is Quadrant IV.', 'Positive x goes right, negative y goes down', 5, 4),
('44444444-0205-0002-0001-000000000005', '33333333-0205-0001-0001-000000000002', 'true_false', 'easy', 'True or False: The point (0, 5) lies on the y-axis.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! When x = 0, the point is on the y-axis (no horizontal movement, only vertical).', 'If x is 0, you have not moved left or right', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0205-0001-0001-000000000003', '22222222-0002-0001-0001-000000000005', 'Line Graphs & Bar Charts', 'Read and interpret common graph types', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0205-0003-0001-000000000001', '33333333-0205-0001-0001-000000000003', 'multiple_choice', 'easy', 'What type of graph is best for showing how something changes over time?', NULL, '[{"id":"a","text":"Pie chart"},{"id":"b","text":"Bar chart"},{"id":"c","text":"Line graph"},{"id":"d","text":"Venn diagram"}]'::jsonb, '"c"'::jsonb, 'Line graphs show trends over time. The x-axis is time, the y-axis is the value, and the line connects the points to show the pattern.', 'Time goes on one axis, values on the other, connected by a line', 5, 1),
('44444444-0205-0003-0001-000000000002', '33333333-0205-0001-0001-000000000003', 'multiple_choice', 'easy', 'On a line graph showing temperature over a week, the line goes upward from Monday to Friday. What does this mean?', NULL, '[{"id":"a","text":"Temperature decreased"},{"id":"b","text":"Temperature stayed the same"},{"id":"c","text":"Temperature increased"},{"id":"d","text":"It rained"}]'::jsonb, '"c"'::jsonb, 'An upward line means the value is increasing. The temperature went up from Monday to Friday.', 'Up = increase, down = decrease', 5, 2),
('44444444-0205-0003-0001-000000000003', '33333333-0205-0001-0001-000000000003', 'true_false', 'easy', 'True or False: A bar chart is best for comparing quantities across categories (like favorite colors in a class).', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Bar charts are perfect for comparing quantities across categories. Each bar represents one category, and the height shows the amount.', 'Think about comparing different groups', 5, 3),
('44444444-0205-0003-0001-000000000004', '33333333-0205-0001-0001-000000000003', 'multiple_choice', 'easy', 'A bar chart shows Book Club has 12 members, Chess Club has 8, and Art Club has 15. Which club is largest?', NULL, '[{"id":"a","text":"Book Club"},{"id":"b","text":"Chess Club"},{"id":"c","text":"Art Club"},{"id":"d","text":"They are equal"}]'::jsonb, '"c"'::jsonb, 'Art Club has 15 members — the tallest bar. Bar charts make comparisons visual and immediate.', 'Which number is biggest?', 5, 4),
('44444444-0205-0003-0001-000000000005', '33333333-0205-0001-0001-000000000003', 'fill_in_blank', 'easy', 'On a graph, the x-axis shows months (Jan=1, Feb=2, etc.) and the y-axis shows sales. In which month were sales highest if the peak of the line is at x = 8?', NULL, NULL, '"August"'::jsonb, 'Month 8 is August. The peak (highest point) of the line shows when sales were greatest.', 'Count the months: January is 1, February is 2...', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0205-0001-0001-000000000004', '22222222-0002-0001-0001-000000000005', 'Interpreting Data', 'Draw conclusions from graphs and charts', 4, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0205-0004-0001-000000000001', '33333333-0205-0001-0001-000000000004', 'multiple_choice', 'easy', 'A line graph shows a sharp downward drop. What does a steep downward line indicate?', NULL, '[{"id":"a","text":"Slow increase"},{"id":"b","text":"No change"},{"id":"c","text":"Rapid decrease"},{"id":"d","text":"Steady growth"}]'::jsonb, '"c"'::jsonb, 'A steep downward line means the value is dropping quickly. The steeper the line, the faster the change.', 'Steepness = speed of change, direction = up or down', 5, 1),
('44444444-0205-0004-0001-000000000002', '33333333-0205-0001-0001-000000000004', 'true_false', 'easy', 'True or False: A flat (horizontal) line on a graph means the value is not changing.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! A horizontal line means the y-value stays the same as x changes. No increase, no decrease.', 'If the line does not go up or down, what is changing?', 5, 2),
('44444444-0205-0004-0001-000000000003', '33333333-0205-0001-0001-000000000004', 'multiple_choice', 'easy', 'A graph shows student test scores improving each month for 6 months, then suddenly dropping in month 7. What is a reasonable explanation?', NULL, '[{"id":"a","text":"The test got harder or students stopped studying"},{"id":"b","text":"The graph is wrong"},{"id":"c","text":"Nothing happened"},{"id":"d","text":"The scores will never recover"}]'::jsonb, '"a"'::jsonb, 'Graphs show patterns, and sudden changes often have causes. A score drop could be a harder test, summer break, or a change in study habits. Good data analysis asks WHY.', 'Think about what could change between months', 5, 3),
('44444444-0205-0004-0001-000000000004', '33333333-0205-0001-0001-000000000004', 'fill_in_blank', 'easy', 'A bar chart shows: Monday = 10 sales, Tuesday = 15, Wednesday = 20, Thursday = 15, Friday = 25. What is the average daily sales? (Type just the number)', NULL, NULL, '"17"'::jsonb, 'Sum = 10 + 15 + 20 + 15 + 25 = 85. Average = 85 ÷ 5 = 17.', 'Add all values, then divide by the number of days', 5, 4),
('44444444-0205-0004-0001-000000000005', '33333333-0205-0001-0001-000000000004', 'multiple_choice', 'easy', 'Which 14th-century scholar used coordinate-like graphs 300 years before Descartes?', NULL, '[{"id":"a","text":"Leonardo da Vinci"},{"id":"b","text":"Nicole Oresme"},{"id":"c","text":"Marco Polo"},{"id":"d","text":"Geoffrey Chaucer"}]'::jsonb, '"b"'::jsonb, 'Nicole Oresme, a French bishop and scholar, plotted velocity against time using coordinate-like graphs in the 1300s — a remarkable precursor to Descartes.', 'He was a French scholar in the 1300s', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0205-0001-0001-000000000005', '22222222-0002-0001-0001-000000000005', 'Graphs Boss Round', 'Prove your graph-reading skills!', 5, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0205-0005-0001-000000000001', '33333333-0205-0001-0001-000000000005', 'fill_in_blank', 'medium', 'Point A is at (3, 7) and Point B is at (3, 2). What is the vertical distance between them?', NULL, NULL, '"5"'::jsonb, 'Both points have x = 3 (same column). Vertical distance = 7 - 2 = 5 units.', 'Same x-coordinate means they are directly above/below each other', 10, 1),
('44444444-0205-0005-0001-000000000002', '33333333-0205-0001-0001-000000000005', 'multiple_choice', 'medium', 'A point is in Quadrant III. What must be true about its coordinates?', NULL, '[{"id":"a","text":"Both x and y are positive"},{"id":"b","text":"x is negative, y is positive"},{"id":"c","text":"Both x and y are negative"},{"id":"d","text":"x is positive, y is negative"}]'::jsonb, '"c"'::jsonb, 'Quadrant III is the bottom-left area. Left = negative x, down = negative y. Both coordinates are negative.', 'Quadrant III is bottom-left', 10, 2),
('44444444-0205-0005-0001-000000000003', '33333333-0205-0001-0001-000000000005', 'fill_in_blank', 'medium', 'If you reflect the point (4, -2) across the x-axis, what is the new y-coordinate?', NULL, NULL, '"2"'::jsonb, 'Reflecting across the x-axis flips the y-coordinate: (4, -2) becomes (4, 2). The x stays the same.', 'Reflection across x-axis changes the sign of y', 10, 3),
('44444444-0205-0005-0001-000000000004', '33333333-0205-0001-0001-000000000005', 'true_false', 'medium', 'True or False: Pierre de Fermat independently developed coordinate geometry around the same time as Descartes.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Fermat and Descartes both developed coordinate geometry independently in the 1630s, though Descartes published first and got more credit.', 'Two mathematicians can discover the same thing at the same time', 10, 4),
('44444444-0205-0005-0001-000000000005', '33333333-0205-0001-0001-000000000005', 'multiple_choice', 'medium', 'Which point is furthest from the origin?', NULL, '[{"id":"a","text":"(3, 0)"},{"id":"b","text":"(2, 2)"},{"id":"c","text":"(0, 4)"},{"id":"d","text":"(1, 1)"}]'::jsonb, '"c"'::jsonb, 'Distance from origin: (3,0)=3, (2,2)=√8≈2.83, (0,4)=4, (1,1)=√2≈1.41. (0, 4) is the furthest at 4 units.', 'Calculate or estimate the distance from (0,0) to each point', 10, 5)
